// Helper function for consistent data processing error handling
function handleDataResult(result, successCallback, errorCallback) {
  if (result.error) {
    errorCallback(result.error);
  } else {
    successCallback(result);
  }
}

// Data validation pipeline
const dataOperations = [
  { type: 'JSON', data: '{"name":"John","age":30}', operation: 'parseJSON' },
  { type: 'XML', data: '<user><name>Jane</name></user>', operation: 'parseXML' },
  { type: 'CSV', data: 'name,age\nBob,25', operation: 'csvToJSON' },
  { type: 'YAML', data: 'name: Alice\nage: 28', operation: 'yamlToJSON' }
];

dataOperations.forEach(({ type, data, operation }, index) => {
  const result = jsonxml.call(operation, data);
  handleDataResult(
    result,
    (processedData) => {
      console.log(`${type} processing (${index + 1}/${dataOperations.length}): Success`);
      console.log('  Processed data:', processedData.data);
      console.log('  Valid:', processedData.valid);
    },
    (error) => {
      console.error(`${type} processing (${index + 1}/${dataOperations.length}) failed: ${error}`);
    }
  );
});

// Universal data format converter with validation
import { loadFromGitHub } from 'gowm';

class DataConverter {
  constructor() {
    this.jsonxml = null;
    this.ready = false;
    this.conversionHistory = [];
    this.loadModule();
  }

  async loadModule() {
    try {
      this.jsonxml = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
        path: 'jsonxml-wasm',
              name: 'jsonxml-wasm'
      });

      // Configure for production use
      this.jsonxml.call('setSilentMode', true);

      // Get available functions
      const functions = this.jsonxml.call('getAvailableFunctions');
      console.log('Available conversion functions:', functions);

      this.ready = true;
    } catch (error) {
      console.error('Failed to load JSONXML module:', error);
    }
  }

  // Universal conversion method
  convert(inputData, fromFormat, toFormat, options = {}) {
    if (!this.ready) {
      throw new Error('JSONXML module not ready');
    }

    if (!inputData) {
      throw new Error('No input data provided');
    }

    const conversionKey = `${fromFormat}To${toFormat.toUpperCase()}`;
    const functionMap = {
      'jsonToXML': 'jsonToXML',
      'xmlToJSON': 'xmlToJSON',
      'csvToJSON': 'csvToJSON',
      'jsonToCSV': 'jsonToCSV',
      'yamlToJSON': 'yamlToJSON',
      'jsonToYAML': 'jsonToYAML'
    };

    const functionName = functionMap[conversionKey];
    if (!functionName) {
      throw new Error(`Conversion from ${fromFormat} to ${toFormat} not supported`);
    }

    // Perform conversion
    const result = options.rootElement && fromFormat === 'json' && toFormat === 'xml'
      ? this.jsonxml.call(functionName, inputData, options.rootElement)
      : this.jsonxml.call(functionName, inputData);

    if (result.error) {
      throw new Error(result.error);
    }

    // Log conversion history
    this.conversionHistory.push({
      from: fromFormat,
      to: toFormat,
      timestamp: new Date().toISOString(),
      inputSize: inputData.length,
      outputSize: typeof result.data === 'string' ? result.data.length : JSON.stringify(result.data).length
    });

    return result;
  }

  // Specific conversion methods
  jsonToXml(jsonData, rootElement = 'root') {
    return this.convert(jsonData, 'json', 'xml', { rootElement });
  }

  xmlToJson(xmlData) {
    return this.convert(xmlData, 'xml', 'json');
  }

  csvToJson(csvData) {
    return this.convert(csvData, 'csv', 'json');
  }

  jsonToCsv(jsonData) {
    return this.convert(jsonData, 'json', 'csv');
  }

  yamlToJson(yamlData) {
    return this.convert(yamlData, 'yaml', 'json');
  }

  jsonToYaml(jsonData) {
    return this.convert(jsonData, 'json', 'yaml');
  }

  // Validation methods
  validateJson(jsonString) {
    if (!this.ready) throw new Error('JSONXML module not ready');

    const result = this.jsonxml.call('validateJSON', jsonString);
    return {
      valid: result.valid,
      errors: result.errors || [],
      data: result.data
    };
  }

  validateXml(xmlString) {
    if (!this.ready) throw new Error('JSONXML module not ready');

    const result = this.jsonxml.call('validateXML', xmlString);
    return {
      valid: result.valid,
      errors: result.errors || [],
      root: result.root
    };
  }

  // Batch conversion utility
  batchConvert(datasets, fromFormat, toFormat) {
    if (!Array.isArray(datasets)) {
      throw new Error('Datasets must be an array');
    }

    const results = [];
    const errors = [];

    datasets.forEach((data, index) => {
      try {
        const result = this.convert(data, fromFormat, toFormat);
        results.push({
          index,
          success: true,
          data: result.data,
          originalSize: data.length,
          convertedSize: typeof result.data === 'string' ? result.data.length : JSON.stringify(result.data).length
        });
      } catch (error) {
        errors.push({
          index,
          error: error.message,
          originalData: data.substring(0, 100) + '...'
        });
      }
    });

    return {
      successful: results.length,
      failed: errors.length,
      results,
      errors
    };
  }

  // Get conversion statistics
  getStats() {
    const formats = [...new Set([
      ...this.conversionHistory.map(h => h.from),
      ...this.conversionHistory.map(h => h.to)
    ])];

    return {
      ready: this.ready,
      totalConversions: this.conversionHistory.length,
      supportedFormats: formats,
      mostUsedConversion: this.getMostUsedConversion(),
      averageInputSize: this.getAverageInputSize(),
      averageOutputSize: this.getAverageOutputSize()
    };
  }

  getMostUsedConversion() {
    const conversions = {};
    this.conversionHistory.forEach(h => {
      const key = `${h.from} → ${h.to}`;
      conversions[key] = (conversions[key] || 0) + 1;
    });

    return Object.entries(conversions).sort((a, b) => b[1] - a[1])[0] || null;
  }

  getAverageInputSize() {
    if (this.conversionHistory.length === 0) return 0;
    const total = this.conversionHistory.reduce((sum, h) => sum + h.inputSize, 0);
    return Math.round(total / this.conversionHistory.length);
  }

  getAverageOutputSize() {
    if (this.conversionHistory.length === 0) return 0;
    const total = this.conversionHistory.reduce((sum, h) => sum + h.outputSize, 0);
    return Math.round(total / this.conversionHistory.length);
  }
}

// Usage example
const converter = new DataConverter();

// Wait for module to load
setTimeout(() => {
  if (converter.ready) {
    try {
      // JSON to XML conversion
      const jsonData = JSON.stringify({
        users: [
          { id: 1, name: 'John Doe', email: 'john@example.com' },
          { id: 2, name: 'Jane Smith', email: 'jane@example.com' }
        ]
      });

      console.log('Converting JSON to XML...');
      const xmlResult = converter.jsonToXml(jsonData, 'userDatabase');
      console.log('XML Result:', xmlResult.data.substring(0, 200) + '...');

      // XML to JSON conversion
      console.log('\nConverting XML back to JSON...');
      const jsonResult = converter.xmlToJson(xmlResult.data);
      console.log('JSON Result:', JSON.stringify(jsonResult.data, null, 2));

      // CSV to JSON conversion
      const csvData = 'id,name,email\n1,John Doe,john@example.com\n2,Jane Smith,jane@example.com';
      console.log('\nConverting CSV to JSON...');
      const csvResult = converter.csvToJson(csvData);
      console.log('CSV to JSON Result:', JSON.stringify(csvResult.data, null, 2));

      // Validation examples
      console.log('\nValidating JSON...');
      const validation = converter.validateJson(jsonData);
      console.log('JSON Valid:', validation.valid);

      // Batch conversion
      console.log('\nBatch conversion test...');
      const batchResults = converter.batchConvert([
        '{"test1": "value1"}',
        '{"test2": "value2"}',
        'invalid json{'
      ], 'json', 'xml');
      console.log('Batch Results:', {
        successful: batchResults.successful,
        failed: batchResults.failed,
        errors: batchResults.errors.map(e => e.error)
      });

      // Statistics
      console.log('\nConverter Statistics:', converter.getStats());

    } catch (error) {
      console.error('Conversion failed:', error.message);
    }
  }
}, 1000);

